export type DirectoryNamePage = {
    data: Array<DirectoryNameEntry>;
    nextCursor: string | null;
};

export type DirectoryNameEntry = {
    id: string;
    /**
     * What this name is to the entity: its current name, a former one, a maiden name, a trading name. An open catalog, not a closed enum.
     */
    nameRole: string;
    /**
     * True for the one name the entity answers to today.
     */
    isCurrent: boolean;
    prefix: string | null;
    given: string | null;
    middle: string | null;
    family: string | null;
    suffix: string | null;
    /**
     * The name as it was recorded. Null for an organization: an organization's name row keeps only the case-folded form, so a caller falls back to normalizedDisplay and shows an honest lowercase former name rather than an invented capitalization.
     */
    displayName: string | null;
    /**
     * The case-folded, punctuation-stripped form the search and conflicts corpus matches on. Always present, for every name row of either kind.
     */
    normalizedDisplay: string;
    validFrom: string | null;
    /**
     * When the name stopped being used, or null while it still is.
     */
    validTo: string | null;
    /**
     * When the firm wrote the row down — which is not when the name came into use. A maiden name recorded onto a twenty-year-old file was recorded today and valid decades ago.
     */
    recordedAt: string;
};

export type DirectoryEntityListingPage = {
    data: Array<DirectoryEntityListing>;
    nextCursor: string | null;
    /**
     * How many records the firm holds under these filters — every page of the walk when the directory is being listed, and the number of records answering when it is being searched, because a ranked answer's size is the answer's and not the book's.
     */
    total: number;
    /**
     * True only where a ranked answer (`search`) was cut short: the firm holds more matches than were returned, so narrowing the query reaches the rest. False on every page of the plain index, which is walkable to its end by cursor and never cut.
     */
    capped: boolean;
};

export type DirectoryEntityListing = {
    entityId: string;
    entityKind: 'person' | 'organization';
    /**
     * What to call the record, or null where the directory holds no name for it at all. A caller shows the gap rather than printing the handle.
     */
    displayName: string | null;
    /**
     * An organization's legal name where it differs from what the firm calls it; null for a person, and null where the two are the same word.
     */
    legalName: string | null;
    /**
     * A person's first name. Null for an organization.
     */
    givenName: string | null;
    /**
     * A person's middle name, where the firm recorded one.
     */
    middleName: string | null;
    /**
     * A person's last name. Null for an organization, and null for a person who has one name — a record with no family name is one the firm keeps, not one it refuses.
     */
    familyName: string | null;
    /**
     * The record's default email address — the primary row where one is marked, else the oldest. Null where the firm holds none. Not a contact register: the record's own contact-points read is where every channel lives.
     */
    emailAddress: string | null;
    /**
     * The record's default number, exactly as it was entered and never rewritten.
     */
    phoneNumber: string | null;
    /**
     * The locality of the record's default address.
     */
    city: string | null;
    /**
     * The administrative area of the default address — state, province, prefecture — where the country has one.
     */
    region: string | null;
    /**
     * The default address's country, ISO 3166-1 alpha-2.
     */
    country: string | null;
    /**
     * When the firm wrote the record down.
     */
    recordedAt: string;
    /**
     * When the record itself last changed. A change to something hanging off it — a name appended, an address added — does not move this.
     */
    changedAt: string;
};

